cd /tmp && node -e "
const A='123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz';
let lines=[];
// deterministic-ish random
let seed=12345; function rnd(){seed=(seed*1103515245+12345)&0x7fffffff; return seed/0x7fffffff;}
for(let i=0;i<250;i++){
  let len=1+Math.floor(rnd()*40);
  let s='';
  // bias heavily toward leading '1's to stress leading-zero handling
  let ones=Math.floor(rnd()*6);
  for(let j=0;j<ones;j++) s+='1';
  for(let j=0;j<len;j++) s+=A[Math.floor(rnd()*58)];
  lines.push(s);
}
// add explicit edge cases
for(let n=0;n<=20;n++) lines.push('1'.repeat(n)||'1');
for(let n=1;n<=20;n++) lines.push('1'.repeat(n)+'z');
for(let n=1;n<=20;n++) lines.push('1'.repeat(n)+'2');
lines.push('z','zz','zzz','zzzz','zzzzz','2','3','1','11','111');
require('fs').writeFileSync('/tmp/bvals.txt',lines.join('\n')+'\n');
console.log('count',lines.length);
"

cd /tmp && node -e "
const crypto=require('crypto');
const dsha=b=>crypto.createHash('sha256').update(crypto.createHash('sha256').update(b).digest()).digest();
// find k where dec1 = 0x00 * k  (i.e. --b = '1'*k) has double-sha256 starting with 0x00
let hits=[];
for(let k=0;k<=4000;k++){
  const d=dsha(Buffer.alloc(k));
  if(d[0]===0) hits.push([k, d.slice(0,4).toString('hex')]);
}
console.log('zeros-prefix hits (k, digest4):', JSON.stringify(hits.slice(0,15)));
let hits2=hits.filter(h=>h[1].startsWith('0000'));
console.log('double-zero hits:', JSON.stringify(hits2));
"
